      hu: ["Mezőgazdasági kereskedelmi központ.", "Fontos csomópont a regionális utazásokhoz."],
      ro: ["Centru pentru comerțul agricol.", "Nod important pentru călătoriile regionale."],
      en: ["Center for agricultural trade.", "Important junction for regional travel."]
